package GUI;
import javafx.geometry.*; import javafx.scene.control.*; import javafx.scene.layout.*; import javafx.scene.shape.SVGPath;
public class AIIntelligenceUI extends ScrollPane {public AIIntelligenceUI(MainUI app){setFitToWidth(true);VBox page=UIFactory.page("AI Intelligence","Choose a focused financial AI tool. Each opens in a dedicated workspace.");HBox top=new HBox(16,launcher("SPENDING ANALYSIS","Analyze spending patterns and trends.","Open Analysis",barChartIcon(),()->app.navigate("Spending Analysis")),launcher("BUDGET RECOMMENDATION","Create a personalized budget using AI.","Open Recommendation",budgetIcon(),()->app.navigate("Budget Recommendation")));top.getChildren().forEach(card->{HBox.setHgrow(card,Priority.ALWAYS);((VBox)card).setPrefWidth(500);});VBox advisor=launcher("AI FINANCIAL ADVISOR","Ask financial questions and receive personalized guidance.","Open Financial Advisor",advisorIcon(),()->app.navigate("Financial Advisor"));page.getChildren().addAll(top,advisor);setContent(page);}private VBox launcher(String title,String text,String action,SVGPath icon,Runnable go){Label heading=new Label(title);if(icon!=null){heading.setGraphic(icon);heading.setContentDisplay(ContentDisplay.LEFT);heading.setGraphicTextGap(10);}heading.getStyleClass().add("ai-launcher-title");Label copy=UIFactory.muted(text);copy.setWrapText(true);Button open=UIFactory.button(action,"ai-button");open.setOnAction(e->go.run());VBox card=new VBox(16,heading,copy,open);card.setPadding(new Insets(28));card.getStyleClass().add("glass-card");return card;}private SVGPath icon(String path){SVGPath icon=new SVGPath();icon.setContent(path);icon.getStyleClass().add("ai-launcher-icon");return icon;}private SVGPath barChartIcon(){return icon("M3,20 L3,11 L7,11 L7,20 Z M10,20 L10,5 L14,5 L14,20 Z M17,20 L17,2 L21,2 L21,20 Z");}private SVGPath budgetIcon(){return icon("M12,3 A9,9 0 1,0 21,12 L12,12 Z M13,3 L13,11 L21,11 A9,9 0 0,0 13,3 Z");}private SVGPath advisorIcon(){return icon("M4,4 L20,4 L20,16 L9,16 L4,20 L4,4 Z M8,9 L16,9 L16,11 L8,11 Z");}}
